const T9_RW_M1: SatQuestion[] = [
  { id: "t9rw1-1", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The diplomat's remarks were carefully ______, designed to soothe both sides without committing her government to anything.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["measured", "reckless", "spontaneous", "hostile"], correct: 0, explanation: "Soothing both sides without committing means the remarks were \"measured\"." },
  { id: "t9rw1-2", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The team of researchers ______ submitting its final report next week.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "were", "have"], correct: 0, explanation: "The subject \"team\" is singular, so \"is\"." },
  { id: "t9rw1-3", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "Mangrove forests trap sediment with their dense roots, building up coastlines and shielding inland areas from storm surges.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Mangroves protect and extend coastlines by trapping sediment.", "Mangroves grow only far inland.", "Mangroves erode the shoreline.", "Mangroves cannot survive near salt water."], correct: 0, explanation: "Trapping sediment builds coastline and shields the land (choice A)." },
  { id: "t9rw1-4", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The factory cut its energy use sharply. ______, its production levels stayed exactly the same.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Therefore", "Nevertheless", "For instance", "Likewise"], correct: 1, explanation: "Less energy yet equal output is a contrast — \"Nevertheless\"." },
  { id: "t9rw1-5", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The recipe calls for three spices ______ cumin, coriander, and turmeric.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["spices, ", "spices: ", "spices; ", "spices "], correct: 1, explanation: "A colon introduces the list that names the three spices." },
  { id: "t9rw1-6", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Although brief, the apology felt ______, and the audience sensed at once that it was sincere.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["heartfelt", "grudging", "rehearsed", "hollow"], correct: 0, explanation: "An apology sensed to be sincere is \"heartfelt\"." },
  { id: "t9rw1-7", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The pass is open to hikers only from June through September; in all other months heavy snow makes it impassable.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["A hiker cannot use the pass in February.", "The pass is open all year.", "Snow never falls on the pass.", "The pass is busiest in winter."], correct: 0, explanation: "February is outside June–September, so the pass is closed (choice A)." },
  { id: "t9rw1-8", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The museum digitized its rare manuscripts. ______, scholars on other continents can now study them without traveling.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "As a result", "Otherwise", "In contrast"], correct: 1, explanation: "Digitizing enables remote study — cause and effect, \"As a result\"." },
  { id: "t9rw1-9", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "Each of the volunteers ______ assigned a different neighborhood to survey.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["were", "was", "are", "have been"], correct: 1, explanation: "\"Each\" is singular, so the singular \"was\"." },
  { id: "t9rw1-10", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The professor's lectures were famously ______, weaving history, art, and economics into a single thread.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["wide-ranging", "narrow", "repetitive", "dull"], correct: 0, explanation: "Weaving several fields together is \"wide-ranging\"." },
  { id: "t9rw1-11", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "A survey found that 80 percent of commuters who switched to cycling reported lower stress, while only 30 percent reported faster trips.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["More cyclists noticed lower stress than noticed faster trips.", "Cycling made trips faster for everyone.", "No cyclists felt less stress.", "Most cyclists reported faster trips."], correct: 0, explanation: "80 percent (stress) exceeds 30 percent (speed), so more noticed lower stress (choice A)." },
  { id: "t9rw1-12", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "Solar panels were once prohibitively expensive. ______, their price has fallen so far that they now rival fossil fuels.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Similarly", "Today", "Therefore", "Furthermore"], correct: 1, explanation: "A shift from the past to the present is signaled by \"Today\"." },
  { id: "t9rw1-13", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The architect designed the bridge, oversaw its construction, and ______ its opening ceremony.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["attending", "attended", "to attend", "attends"], correct: 1, explanation: "Parallel with \"designed\" and \"oversaw\" requires \"attended\"." },
  { id: "t9rw1-14", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The witness gave a ______ account, recalling details that even the investigators had overlooked.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["meticulous", "careless", "hazy", "brief"], correct: 0, explanation: "Recalling overlooked details shows a \"meticulous\" account." },
  { id: "t9rw1-15", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The grant funds research only in renewable energy; proposals on other topics are returned without review.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["A proposal on wind power could be considered for the grant.", "Any research topic qualifies for the grant.", "Renewable-energy proposals are rejected automatically.", "The grant reviews all proposals it receives."], correct: 0, explanation: "Wind power is renewable energy, so it could be considered (choice A)." },
  { id: "t9rw1-16", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The startup missed its first deadline. ______, it lost the confidence of two early investors.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Nonetheless", "Consequently", "However", "Meanwhile"], correct: 1, explanation: "Losing investors is a consequence of the miss — \"Consequently\"." },
  { id: "t9rw1-17", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The novelist published her debut in 2010 ______ she had been writing privately for nearly a decade before that.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["2010, but", "2010 but", "2010; but", "2010: but"], correct: 0, explanation: "A comma before the coordinating conjunction \"but\" joins two independent clauses." },
  { id: "t9rw1-18", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Rather than condemning the old theory outright, the paper treats it as a ______ — useful in its day, now superseded.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["stepping-stone", "dead end", "fabrication", "masterpiece"], correct: 0, explanation: "Useful then but now superseded fits a \"stepping-stone\"." },
  { id: "t9rw1-19", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The author begins by recounting a personal failure, then uses it to introduce the broader argument that mistakes drive learning.", prompt: "Which choice best describes the function of the personal failure?", type: "mcq", choices: ["It serves as a concrete entry point into the author's larger argument.", "It states the essay's final conclusion.", "It lists unrelated definitions.", "It contradicts the author's thesis."], correct: 0, explanation: "The anecdote leads into the broader claim (choice A)." },
  { id: "t9rw1-20", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The vaccine requires storage at very low temperatures. ______, distributing it to rural clinics has proved difficult.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["For this reason", "By contrast", "Even so", "Nonetheless"], correct: 0, explanation: "The cold requirement causes the difficulty — \"For this reason\"." },
  { id: "t9rw1-21", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The orchestra, along with its guest soloists, ______ tuning before the performance.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["are", "is", "were", "have"], correct: 1, explanation: "The subject is singular \"orchestra\"; the \"along with\" phrase doesn't change number, so \"is\"." },
  { id: "t9rw1-22", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The critic praised the film's ______ tone, which moved easily between comedy and grief without jarring the viewer.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["versatile", "monotonous", "rigid", "shrill"], correct: 0, explanation: "Moving smoothly between moods is \"versatile\"." },
  { id: "t9rw1-23", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "All ticket holders receive a printed program; members also receive a backstage tour.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["A member receives both a program and a backstage tour.", "Non-members receive the backstage tour.", "No one receives a printed program.", "Members do not receive a program."], correct: 0, explanation: "All ticket holders get the program, and members also get the tour (choice A)." },
  { id: "t9rw1-24", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "Walking through the quiet gallery, ______ noticed a small painting tucked into a corner.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["the painting", "she", "there", "it"], correct: 1, explanation: "The modifier \"walking through the gallery\" must describe a person — \"she\"." },
  { id: "t9rw1-25", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "His optimism was not naive but ______ — earned through years of setbacks he had learned to outlast.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["hard-won", "effortless", "groundless", "fleeting"], correct: 0, explanation: "Earned through years of setbacks makes the optimism \"hard-won\"." },
  { id: "t9rw1-26", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "Whereas the older map relied on guesswork for uncharted regions, the new one is built entirely from satellite imagery.", prompt: "Which choice best describes the main purpose of the text?", type: "mcq", choices: ["To contrast the methods behind two maps.", "To argue that guesswork is best.", "To describe only the older map.", "To dismiss satellite imagery as unreliable."], correct: 0, explanation: "\"Whereas … the new one …\" contrasts the two maps' methods (choice A)." },
  { id: "t9rw1-27", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The trail crew cleared the fallen trees and rebuilt the washed-out steps. ______, hikers were able to return to the route within days.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Thus", "However", "Instead", "Otherwise"], correct: 0, explanation: "The repairs allow the return — a result, \"Thus\"." },
];

