const T9_RW_M2E: SatQuestion[] = [
  { id: "t9rw2e-1", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The soup was too ______, so I added more water to thin it out.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["thick", "thin", "cold", "sweet"], correct: 0, explanation: "Adding water to thin it means it was too \"thick\"." },
  { id: "t9rw2e-2", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The dogs ______ barking at the mail carrier.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "\"Dogs\" is plural, so \"are\"." },
  { id: "t9rw2e-3", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Plants use sunlight, water, and air to make their own food through a process called photosynthesis.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Plants make their own food using sunlight, water, and air.", "Plants eat other animals for food.", "Plants do not need sunlight.", "Plants cannot make food at all."], correct: 0, explanation: "Photosynthesis lets plants make food from sunlight, water, and air (choice A)." },
  { id: "t9rw2e-4", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The bus was late this morning. ______, I arrived at school after the bell.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "As a result", "For example", "Instead"], correct: 1, explanation: "Arriving late is the result of the late bus — \"As a result\"." },
  { id: "t9rw2e-5", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Yesterday we ______ a movie at the new theater downtown.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["watch", "watches", "watched", "watching"], correct: 2, explanation: "\"Yesterday\" requires the past tense \"watched\"." },
  { id: "t9rw2e-6", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The library was ______, so we could hear ourselves think.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["quiet", "loud", "crowded", "bright"], correct: 0, explanation: "Being able to think clearly means it was \"quiet\"." },
  { id: "t9rw2e-7", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Brushing your teeth twice a day removes food, prevents cavities, and keeps your breath fresh.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Brushing teeth has several benefits.", "Brushing teeth causes cavities.", "Brushing teeth is unnecessary.", "Brushing only freshens breath."], correct: 0, explanation: "Three benefits are listed — choice A." },
  { id: "t9rw2e-8", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "She wore ______ orange scarf to the festival.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["a", "an", "the only", "some"], correct: 1, explanation: "\"Orange\" begins with a vowel sound, so \"an\"." },
  { id: "t9rw2e-9", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The runner was ______ after finishing the long race.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["exhausted", "energetic", "bored", "hungry"], correct: 0, explanation: "After a long race a runner is \"exhausted\"." },
  { id: "t9rw2e-10", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The cat licked ______ paws after the meal.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["its", "it's", "their", "they're"], correct: 0, explanation: "Singular \"cat\" takes the possessive \"its\"." },
  { id: "t9rw2e-11", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The store offers free shipping on orders over $50; smaller orders pay a flat $5 fee.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["A $20 order pays a $5 shipping fee.", "Every order ships for free.", "A $60 order pays $5 shipping.", "All orders pay $5 shipping."], correct: 0, explanation: "A $20 order is under $50, so it pays the $5 fee (choice A)." },
  { id: "t9rw2e-12", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "I wanted to learn guitar. ______, I signed up for weekly lessons.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "So", "Otherwise", "In contrast"], correct: 1, explanation: "Signing up follows from the wish — \"So\"." },
  { id: "t9rw2e-13", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "There ______ several books on the table this morning.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["was", "were", "is", "has been"], correct: 1, explanation: "The subject \"books\" is plural, so \"were\"." },
  { id: "t9rw2e-14", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The new restaurant was very ______, with long lines out the door every night.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["popular", "empty", "expensive", "quiet"], correct: 0, explanation: "Long lines every night show it was \"popular\"." },
  { id: "t9rw2e-15", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "Owls hunt mainly at night, using sharp hearing and silent flight to surprise their prey.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Owls are adapted for hunting at night.", "Owls hunt only in daylight.", "Owls cannot fly quietly.", "Owls have poor hearing."], correct: 0, explanation: "Night hunting, sharp hearing, and silent flight all describe nocturnal adaptation (choice A)." },
  { id: "t9rw2e-16", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The first batch of cookies burned. ______, we lowered the oven temperature for the second batch.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Therefore", "However", "Meanwhile", "Likewise"], correct: 0, explanation: "Lowering the temperature responds to the burning — \"Therefore\"." },
  { id: "t9rw2e-17", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "My brother and I ______ going to the concert together.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "am", "are", "was"], correct: 2, explanation: "The compound subject \"brother and I\" is plural, so \"are\"." },
  { id: "t9rw2e-18", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The directions were simple and ______, so no one got lost.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["clear", "confusing", "long", "secret"], correct: 0, explanation: "No one getting lost means the directions were \"clear\"." },
  { id: "t9rw2e-19", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "Recycling one ton of paper saves about 17 trees and a large amount of water and energy.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Recycling paper conserves trees and other resources.", "Recycling paper wastes resources.", "Recycling paper has no benefits.", "Recycling paper requires cutting more trees."], correct: 0, explanation: "It saves trees, water, and energy — conserving resources (choice A)." },
  { id: "t9rw2e-20", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "He packed his bag, locked the door, and ______ for the airport.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["leaving", "left", "to leave", "leaves"], correct: 1, explanation: "Parallel with \"packed\" and \"locked\" requires \"left\"." },
  { id: "t9rw2e-21", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The garden needed more sun. ______, we moved the planters to the south side of the yard.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Nevertheless", "So", "However", "Instead"], correct: 1, explanation: "Moving the planters is the response to needing sun — \"So\"." },
  { id: "t9rw2e-22", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The coach's praise was ______, never given unless it was truly earned.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["sparing", "constant", "empty", "loud"], correct: 0, explanation: "Given only when earned means the praise was \"sparing\"." },
  { id: "t9rw2e-23", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "All members may borrow up to five books; first-year members may borrow only three.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["A second-year member may borrow up to five books.", "First-year members may borrow ten books.", "No members may borrow any books.", "Every member may borrow only three books."], correct: 0, explanation: "The five-book limit applies to members who aren't first-years (choice A)." },
  { id: "t9rw2e-24", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The chef chopped the onions ______ then added them to the sizzling pan.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["onions, and", "onions and", "onions; and", "onions: and"], correct: 0, explanation: "A comma before \"and\" joins the two independent clauses." },
  { id: "t9rw2e-25", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The lecture was ______, packing a semester's worth of ideas into a single hour.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["dense", "shallow", "rambling", "empty"], correct: 0, explanation: "Packing a semester into an hour is \"dense\"." },
  { id: "t9rw2e-26", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The article first describes the problem of plastic waste, then surveys three proposed solutions in turn.", prompt: "Which choice best describes the structure of the text?", type: "mcq", choices: ["A problem is stated and then possible solutions are reviewed.", "A single solution is rejected outright.", "Only the history of plastic is told.", "Two unrelated topics are compared."], correct: 0, explanation: "Problem first, then a survey of solutions (choice A)." },
  { id: "t9rw2e-27", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "Ticket sales were strong all summer. ______, the festival earned enough to fund next year's event.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "As a result", "Otherwise", "In contrast"], correct: 1, explanation: "Funding follows from strong sales — \"As a result\"." },
];

// ─────────────────────────── R&W MODULE 2 HARD (med/hard, 27) ───────────────────────────
const T9_RW_M2H: SatQuestion[] = [
  { id: "t9rw2h-1", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The memoir is admirably ______: the author refuses to flatter herself, dwelling as readily on her failures as on her triumphs.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["candid", "evasive", "boastful", "guarded"], correct: 0, explanation: "Dwelling honestly on failures is \"candid\"." },
  { id: "t9rw2h-2", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The essay opens with a sweeping generalization, then devotes its remaining pages to the exceptions that complicate it.", prompt: "Which choice best describes the function of the opening generalization?", type: "mcq", choices: ["It sets up a claim the essay then qualifies with exceptions.", "It states the essay's settled conclusion.", "It lists technical definitions.", "It ends the essay's argument."], correct: 0, explanation: "The broad claim is later complicated by exceptions (choice A)." },
  { id: "t9rw2h-3", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A reservoir held 120 million liters in spring, 95 million in early summer, and 92 million by late summer.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["The sharpest drop occurred between spring and early summer.", "The reservoir gained water over the period.", "Late summer saw the steepest decline.", "The level stayed constant all year."], correct: 0, explanation: "120 to 95 is a 25 drop; 95 to 92 is a 3 drop — the sharpest fall is spring to early summer (choice A)." },
  { id: "t9rw2h-4", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The treaty is widely admired for its idealism. ______, it lacks any mechanism to enforce the obligations it so eloquently describes.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Therefore", "Yet", "Likewise", "Accordingly"], correct: 1, explanation: "Admiration followed by a serious flaw is a contrast — \"Yet\"." },
  { id: "t9rw2h-5", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The internship trains participants to gather data carefully, to interpret it rigorously, and ______ it clearly.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["to present", "presenting", "present", "presented"], correct: 0, explanation: "Parallel with \"to gather\" and \"to interpret\" requires \"to present\"." },
  { id: "t9rw2h-6", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Her prose is ______, every clause stripped of anything that does not earn its place.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["spare", "ornate", "rambling", "verbose"], correct: 0, explanation: "Stripped of the unnecessary, the prose is \"spare\"." },
  { id: "t9rw2h-7", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Whereas the first biographer accepted the legend uncritically, the second tests each anecdote against surviving letters and records.", prompt: "Which choice best describes the main purpose of the text?", type: "mcq", choices: ["To contrast two biographers' approaches to evidence.", "To argue that legends are reliable history.", "To summarize only the first biography.", "To praise the legend as fact."], correct: 0, explanation: "\"Whereas … the second …\" contrasts the biographers' use of evidence (choice A)." },
  { id: "t9rw2h-8", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "Neither the manager nor her assistants ______ aware that the shipment had already arrived.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["was", "were", "is", "has been"], correct: 1, explanation: "With \"neither … nor,\" the verb agrees with the nearer subject — plural \"assistants\" — so \"were\"." },
  { id: "t9rw2h-9", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The general's strategy was ______: each apparent retreat was, in fact, a calculated step toward a larger encirclement.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["cunning", "haphazard", "transparent", "reckless"], correct: 0, explanation: "Disguised retreats serving a plan are \"cunning\"." },
  { id: "t9rw2h-10", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "In a trial, plants given the new nutrient grew 40 percent taller than untreated plants, but they also flowered two weeks later.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["The nutrient increased height but delayed flowering.", "The nutrient had no measurable effect.", "Treated plants flowered earlier.", "Treated plants were shorter."], correct: 0, explanation: "Taller growth plus later flowering means a height gain and a flowering delay (choice A)." },
  { id: "t9rw2h-11", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The algorithm sorts millions of records in seconds. ______, it stumbles on the small, irregular datasets that humans handle with ease.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Hence", "Paradoxically", "Therefore", "Consequently"], correct: 1, explanation: "Excelling at the huge but failing at the small is an apparent contradiction — \"Paradoxically\"." },
  { id: "t9rw2h-12", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The expedition reached the summit at dawn ______ a feat no team had managed in the storm-plagued season.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["dawn,", "dawn;", "dawn:", "dawn"], correct: 0, explanation: "A comma sets off the appositive phrase \"a feat …\" describing the achievement." },
  { id: "t9rw2h-13", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Far from being ______, the committee's silence was a deliberate tactic meant to pressure the other side into speaking first.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["passive", "strategic", "calculated", "intentional"], correct: 0, explanation: "\"Far from being ___ … deliberate tactic\" requires the opposite of deliberate — \"passive\"." },
  { id: "t9rw2h-14", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The author concedes that her data are limited, then argues that even this partial evidence points unmistakably in one direction.", prompt: "Which choice best describes the function of the concession?", type: "mcq", choices: ["It acknowledges a weakness before arguing the evidence still holds.", "It abandons the argument entirely.", "It introduces an unrelated topic.", "It restates the opposing thesis approvingly."], correct: 0, explanation: "She admits the limit, then argues the evidence still points one way (choice A)." },
  { id: "t9rw2h-15", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The committee reviewed the proposal, revised its budget, and ______ it to the board for final approval.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["submitting", "submitted", "to submit", "submits"], correct: 1, explanation: "Parallel with \"reviewed\" and \"revised\" requires \"submitted\"." },
  { id: "t9rw2h-16", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The painting's appeal is ______: at first it seems merely pretty, but each viewing reveals deeper layers of meaning.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["cumulative", "instantaneous", "fleeting", "superficial"], correct: 0, explanation: "Appeal that deepens with each viewing is \"cumulative\"." },
  { id: "t9rw2h-17", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Of three coatings tested, the first lasted 4 years, the second 11 years, and the third 12 years before failing.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["The jump in durability was far greater from the first to the second coating than from the second to the third.", "All three coatings lasted the same time.", "The first coating lasted longest.", "The third coating failed first."], correct: 0, explanation: "4 to 11 is +7 years; 11 to 12 is +1 — the big jump is first to second (choice A)." },
  { id: "t9rw2h-18", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The reforms reduced waiting times dramatically. ______, patient satisfaction scores barely moved, suggesting that speed was not the chief concern.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Accordingly", "However", "Therefore", "Hence"], correct: 1, explanation: "Faster service yet flat satisfaction is a contrast — \"However\"." },
  { id: "t9rw2h-19", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The bridge, which engineers had declared sound only months earlier ______ closed for emergency repairs.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["earlier, was", "earlier was", "earlier; was", "earlier: was"], correct: 0, explanation: "A comma closes the nonrestrictive clause before the main verb \"was\"." },
  { id: "t9rw2h-20", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "His arguments were so ______ that opponents struggled to find any opening through which to attack them.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["airtight", "porous", "flimsy", "tentative"], correct: 0, explanation: "Leaving no opening for attack makes arguments \"airtight\"." },
  { id: "t9rw2h-21", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Rather than treating folklore as mere entertainment, the scholar reads each tale as a coded record of the community's deepest anxieties.", prompt: "Which choice best describes the scholar's approach?", type: "mcq", choices: ["She interprets folktales as evidence of a community's underlying fears.", "She dismisses folktales as meaningless.", "She studies only modern entertainment.", "She argues folktales have no cultural value."], correct: 0, explanation: "She reads tales as coded records of anxieties (choice A)." },
  { id: "t9rw2h-22", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The data, collected over a decade by dozens of volunteers, ______ finally ready for analysis.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["were", "was", "is", "being"], correct: 0, explanation: "Treated as a plural set of figures, \"data\" takes \"were\"; the intervening phrase doesn't change the subject." },
  { id: "t9rw2h-23", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The biography is ______, refusing to settle on a single verdict and leaving its subject as contradictory as he was in life.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["unresolved", "conclusive", "simplistic", "one-sided"], correct: 0, explanation: "Refusing a single verdict leaves the portrait \"unresolved\"." },
  { id: "t9rw2h-24", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The paper argues that the famine, long blamed on drought alone, was driven equally by trade policies that drained local grain reserves.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["The famine had a political cause alongside the drought.", "Drought alone fully explains the famine.", "Trade policy prevented the famine.", "The famine never actually occurred."], correct: 0, explanation: "Trade policy is named as an equal driver alongside drought (choice A)." },
  { id: "t9rw2h-25", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The instrument can detect a single photon. ______, it must be cooled to near absolute zero, which makes it costly to operate.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Likewise", "To achieve this", "Nevertheless", "In contrast"], correct: 1, explanation: "The cooling is what enables the detection — \"To achieve this\"." },
  { id: "t9rw2h-26", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "Drawn by tales of gold ______ prospectors flooded the valley within a single year.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["gold,", "gold;", "gold:", "gold"], correct: 0, explanation: "A comma follows the introductory participial phrase \"drawn by tales of gold\"." },
  { id: "t9rw2h-27", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The verdict was ______: while it cleared the defendant of the gravest charge, it left a cloud of lesser suspicions intact.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["equivocal", "decisive", "unanimous", "absolute"], correct: 0, explanation: "Clearing one charge but leaving suspicions makes the verdict \"equivocal\"." },
];

